-- DUMMY DATA: approval policies (Watchtower library approval_policies). One record per approval point on the platform,
-- so the library documents who approves what (see docs/APPROVALS.md). Values are demo settings, not adm Indicia policy.
-- Records are inserted active; later changes go through the library's maker-checker.

insert into public.library_records (library_key, code, name, data, status, effective_from, notes)
select 'approval_policies', x.code, x.name, x.data::jsonb, 'active', '2026-01-01'::date, 'Demo policy'
from (values
  -- Watchtower
  ('AP-LIBRARY', 'Library change (maker-checker libraries)', '{"module":"watchtower","approval_type":"LIBRARY","approver_role":"module_owner","maker_checker":true,"sla_days":5,"description":"New or superseding versions of libraries marked requires approval (core principles, DOA, Impact Grade, POD checklist, display scoring, finance rules, approval policies...).","decided_in":"library_approve","where_in_ui":"/watchtower/libraries/<library>"}'),
  ('AP-RATE-CARD', 'Rate card change', '{"module":"sourcing","approval_type":"RATE_CARD","approver_role":"module_owner","maker_checker":true,"sla_days":3,"description":"Rate card versions only go live once a second Sourcing+ governor approves them.","decided_in":"library_approve","where_in_ui":"/sourcing/watchtower/libraries/rate_cards"}'),
  ('AP-CR-REVIEW', 'Change request review', '{"module":"watchtower","approval_type":"CR_REVIEW","approver_role":"module_owner","maker_checker":false,"sla_days":10,"description":"Review a suggested change against the core principles (every principle in the category checked, 20 second minimum).","decided_in":"cr_review","where_in_ui":"/watchtower/change-requests"}'),
  ('AP-CR-VERIFY', 'Change request verification', '{"module":"watchtower","approval_type":"CR_VERIFY","approver_role":"module_owner","maker_checker":true,"sla_days":5,"description":"Verify an implemented change; never the person who implemented it.","decided_in":"cr_verify","where_in_ui":"/watchtower/change-requests"}'),
  ('AP-SCORECARD', 'Scorecard methodology activation', '{"module":"assure","approval_type":"SCORECARD","approver_role":"admin","maker_checker":false,"description":"Make a draft supplier scorecard methodology live (weights must add up).","decided_in":"scorecard_activate","where_in_ui":"/assure/watchtower/methodology"}'),
  -- Briefing+
  ('AP-BRIEF', 'Brief approval', '{"module":"briefing","approval_type":"BRIEF","approver_role":"briefing_lead","maker_checker":true,"sla_days":3,"description":"A submitted brief is approved (opens ideation) or sent back with changes. Never the author.","decided_in":"brief_decide","where_in_ui":"/briefing/<brief>"}'),
  ('AP-CONCEPT', 'Concept approval before hand-off', '{"module":"briefing","approval_type":"CONCEPT","approver_role":"briefing_lead","maker_checker":true,"client_approval_required":false,"sla_days":3,"description":"A concept is approved before it is sent to Sourcing+ (or, for campaign ideation, before briefs are created from it). Never the submitter.","decided_in":"concept_decide","where_in_ui":"/briefing/<brief>#concepts"}'),
  ('AP-CONCEPT-HIGH', 'Concept approval: high budget', '{"module":"briefing","approval_type":"CONCEPT","approver_role":"procurement_head","min_value":40000,"maker_checker":true,"sla_days":3,"description":"Concepts on briefs with a top budget of 40,000 or more need the Procurement head.","decided_in":"concept_decide","where_in_ui":"/briefing/<brief>#concepts"}'),
  ('AP-CONCEPT-HNK', 'Concept approval: Heineken (client signs off)', '{"module":"briefing","approval_type":"CONCEPT","approver_role":"briefing_lead","client_code":"HNK","maker_checker":true,"client_approval_required":true,"sla_days":3,"description":"Heineken concepts are approved internally, then by a Heineken approver in the Client Portal, before they go to Sourcing+.","decided_in":"concept_decide, client_concept_decide","where_in_ui":"/briefing/<brief>#concepts and /client-portal/briefs/<brief>"}'),
  ('AP-CONCEPT-CLIENT', 'Client concept approval', '{"module":"briefing","approval_type":"CONCEPT_CLIENT","approver_role":"client_approver","maker_checker":false,"client_approval_required":true,"sla_days":5,"description":"The client approver approves or asks for changes on an internally approved concept. Viewers cannot decide.","decided_in":"client_concept_decide","where_in_ui":"/client-portal/briefs/<brief>"}'),
  -- RFQ+ / Sourcing+
  ('AP-RFQ-HIGH-VALUE', 'High-value RFQ release', '{"module":"rfq","approval_type":"RFQ_HIGH_VALUE","approver_role":"sourcing_lead","maker_checker":true,"sla_days":2,"description":"An RFQ at or over the market threshold (high_value_thresholds library) needs a sourcing lead before it goes out.","decided_in":"rfq_approve_high_value","where_in_ui":"/rfq/<rfq>"}'),
  ('AP-QUOTE-FINANCE', 'Quote finance approval', '{"module":"rfq","approval_type":"QUOTE_FINANCE","approver_role":"finance","maker_checker":false,"sla_days":2,"description":"Finance approves or declines each submitted quote; only a finance-approved quote can be awarded.","decided_in":"rfq_finance_decide","where_in_ui":"/finance/approvals"}'),
  ('AP-RFQ-AWARD', 'RFQ award', '{"module":"rfq","approval_type":"RFQ_AWARD","approver_role":"internal","maker_checker":false,"description":"Award after bidding closes: finance-approved quote, supplier eligible in SRM, minimum quotes or a governed bypass reason.","decided_in":"rfq_award","where_in_ui":"/rfq/<rfq>"}'),
  ('AP-PUSH-PRICE', 'Pushed price (vendor)', '{"module":"sourcing","approval_type":"PUSH_PRICE","approver_role":"vendor","maker_checker":false,"sla_days":3,"description":"The vendor accepts or declines a pushed rate-card price by the respond-by date.","decided_in":"triage_push_respond","where_in_ui":"/vendor (pushed prices)"}'),
  -- Order Management+
  ('AP-ESTIMATE-CLIENT', 'Client estimate decision', '{"module":"orders","approval_type":"ESTIMATE_CLIENT","approver_role":"client_approver","maker_checker":false,"client_approval_required":true,"sla_days":5,"description":"The client approver decides in the Client Portal; internal staff confirm the approval (hands off to Stocktool).","decided_in":"client_estimate_decide, estimate_approve","where_in_ui":"/client-portal/estimates and /orders/estimates/<estimate>"}'),
  ('AP-PO-DOA', 'Purchase order (delegated authority)', '{"module":"orders","approval_type":"PO_DOA","approver_role":"doa","maker_checker":true,"sla_days":2,"description":"DOA level from the doa_levels library by PO value; never the person who raised the PO.","decided_in":"po_approve","where_in_ui":"/orders/purchase-orders/<po>"}'),
  ('AP-PSA-LM', 'PSA exception: line manager', '{"module":"orders","approval_type":"PSA_LINE_MANAGER","approver_role":"named_person","maker_checker":true,"sla_days":3,"description":"The line manager named by the requester verifies the request.","decided_in":"psa_line_manager_decide","where_in_ui":"/orders/psa/<psa>"}'),
  ('AP-PSA-ASSESS', 'PSA exception: procurement assessment', '{"module":"orders","approval_type":"PSA_ASSESS","approver_role":"procurement","maker_checker":true,"sla_days":5,"description":"Regional procurement SME or sourcing lead assesses the exception.","decided_in":"psa_assess","where_in_ui":"/orders/psa/<psa>"}'),
  ('AP-PSA-APPROVE', 'PSA exception: delegated approver', '{"module":"orders","approval_type":"PSA_APPROVE","approver_role":"doa","maker_checker":true,"sla_days":3,"description":"DOA level by fee; never the requester.","decided_in":"psa_approve","where_in_ui":"/orders/psa/<psa>"}'),
  ('AP-PSA-APPLY', 'PSA exception: apply', '{"module":"orders","approval_type":"PSA_APPLY","approver_role":"finance","maker_checker":false,"sla_days":5,"description":"Finance (FSSC / CST) applies the approved fee exception.","decided_in":"psa_apply","where_in_ui":"/orders/psa/<psa>"}'),
  -- Finance+
  ('AP-ESTIMATE-FINANCE', 'Estimate finance review', '{"module":"finance","approval_type":"ESTIMATE_FINANCE","approver_role":"finance","maker_checker":false,"sla_days":2,"description":"Estimates with margin under FR-MIN-MARGIN, value at or over FR-REVIEW-VALUE, or a minimum-quotes bypass.","decided_in":"finance_estimate_decide","where_in_ui":"/finance/approvals"}'),
  ('AP-INVOICE', 'Supplier invoice approval', '{"module":"finance","approval_type":"INVOICE_APPROVE","approver_role":"finance","maker_checker":false,"sla_days":5,"description":"Approve a matched supplier invoice after the three-way match.","decided_in":"finance_approve_invoice","where_in_ui":"/finance/invoices/<invoice>"}'),
  ('AP-INVOICE-OVERRIDE', 'Invoice match override', '{"module":"finance","approval_type":"INVOICE_OVERRIDE","approver_role":"finance","maker_checker":true,"sla_days":3,"description":"An unmatched invoice needs an override reason from one finance user and approval from another.","decided_in":"finance_request_override, finance_approve_invoice","where_in_ui":"/finance/invoices/<invoice>"}'),
  ('AP-BILL-SEND', 'Client bill', '{"module":"finance","approval_type":"BILL_SEND","approver_role":"finance","maker_checker":false,"description":"Finance creates and sends a client bill from an approved estimate.","decided_in":"finance_bill_create, finance_bill_send","where_in_ui":"/finance/billing"}'),
  -- Logistics+
  ('AP-POD', 'Proof of delivery verification', '{"module":"logistics","approval_type":"POD_VERIFY","approver_role":"internal","maker_checker":true,"sla_days":2,"description":"Every mandatory POD checklist point checked; never the uploader.","decided_in":"logistics_pod_verify, logistics_pod_reject","where_in_ui":"/logistics/pods"}'),
  -- Execution+
  ('AP-DEPLOYMENT-AUDIT', 'Deployment audit', '{"module":"execution","approval_type":"DEPLOYMENT_AUDIT","approver_role":"internal","maker_checker":true,"sla_days":3,"description":"Score an installed display against the display scoring library; never who recorded the install.","decided_in":"execution_audit_deployment","where_in_ui":"/execution/deployments/<deployment>"}'),
  ('AP-QUALITY-GATE', 'Quality gate sign-off', '{"module":"execution","approval_type":"QUALITY_GATE","approver_role":"internal","maker_checker":false,"sla_days":3,"description":"Mock-up, production, installation and closure gates in order, each with its check sheet.","decided_in":"execution_gate_sign_off","where_in_ui":"/execution/jobs/<job>"}'),
  ('AP-JOB-CLOSE', 'Job close override', '{"module":"execution","approval_type":"JOB_CLOSE","approver_role":"internal","maker_checker":false,"description":"Close a job with open soft checks by giving an override reason.","decided_in":"execution_close_job","where_in_ui":"/execution/jobs/<job>"}'),
  -- SRM (SRT desk and SRM) and the vendor portal
  ('AP-SRT-GATE', 'Onboarding gate verification', '{"module":"assure","approval_type":"SRT_GATE","approver_role":"srt_agent","maker_checker":false,"sla_days":5,"description":"SRT agents or leads verify or reject received evidence on a gate.","decided_in":"update_supplier_gate","where_in_ui":"/assure/suppliers/<supplier>"}'),
  ('AP-SRT-BANK', 'Bank details verification', '{"module":"assure","approval_type":"SRT_BANK","approver_role":"finance","maker_checker":false,"sla_days":3,"description":"Finance verifies the bank details gate.","decided_in":"update_supplier_gate","where_in_ui":"/assure/suppliers/<supplier>"}'),
  ('AP-SRT-APPROVAL', 'Onboarding approval (Procurement head)', '{"module":"assure","approval_type":"SRT_ONBOARDING_APPROVAL","approver_role":"procurement_head","maker_checker":false,"sla_days":3,"description":"Final onboarding approval gate.","decided_in":"update_supplier_gate","where_in_ui":"/assure/suppliers/<supplier>"}'),
  ('AP-FAST-TRACK', 'Fast-track onboarding exception', '{"module":"assure","approval_type":"FAST_TRACK","approver_role":"srt_lead","maker_checker":true,"description":"An SRT lead approves a fast-track route with a justification and close-by date; not for a supplier they created.","decided_in":"approve_fast_track","where_in_ui":"/assure/suppliers/<supplier>"}'),
  ('AP-VENDOR-RFI', 'Vendor information review', '{"module":"assure","approval_type":"VENDOR_RFI","approver_role":"procurement_head","maker_checker":false,"sla_days":3,"description":"Approve, return or reject what the vendor submitted.","decided_in":"review_vendor_rfi","where_in_ui":"/assure/srt/tickets/<ticket>"}'),
  ('AP-CERTIFICATE', 'Certificate verification', '{"module":"assure","approval_type":"CERTIFICATE","approver_role":"internal","maker_checker":true,"sla_days":5,"description":"Verify or reject a supplier certificate; never the uploader.","decided_in":"assure_review_certificate","where_in_ui":"/assure/compliance/review"}'),
  ('AP-DOCUMENT', 'Control document review', '{"module":"assure","approval_type":"DOCUMENT","approver_role":"internal","maker_checker":true,"sla_days":5,"description":"Verify or reject an uploaded control document; never the uploader.","decided_in":"assure_review_document","where_in_ui":"/assure/compliance/review"}'),
  ('AP-PRE-ASSESS-VM', 'Pre-assessment: vendor manager', '{"module":"assure","approval_type":"PRE_ASSESSMENT_VM","approver_role":"srt_agent","maker_checker":false,"sla_days":5,"description":"Vendor manager reviews a submitted pre-assessment.","decided_in":"assure_pa_transition","where_in_ui":"/assure/pre-assessments/<id>"}'),
  ('AP-PRE-ASSESS-PROC', 'Pre-assessment: procurement', '{"module":"assure","approval_type":"PRE_ASSESSMENT_PROCUREMENT","approver_role":"procurement","maker_checker":true,"sla_days":10,"description":"Procurement sends terms and confirms onboarding; not the vendor-manager reviewer.","decided_in":"assure_pa_transition","where_in_ui":"/assure/pre-assessments/<id>"}'),
  ('AP-REVIEW-OUTCOMES', 'Business review outcomes', '{"module":"assure","approval_type":"REVIEW_OUTCOMES","approver_role":"procurement_head","maker_checker":true,"sla_days":5,"description":"Procurement head approves business review outcomes; never the review author.","decided_in":"assure_review_approve_outcomes","where_in_ui":"/assure/reviews/<review>"}'),
  ('AP-SURVEY', 'Survey response review', '{"module":"assure","approval_type":"SURVEY_REVIEW","approver_role":"internal","maker_checker":false,"sla_days":5,"description":"Approve or reject a vendor survey response.","decided_in":"assure_survey_review","where_in_ui":"/assure/surveys"}'),
  ('AP-WORKFLOW-STEP', 'Workflow step', '{"module":"assure","approval_type":"WORKFLOW_STEP","approver_role":"internal","maker_checker":true,"sla_days":5,"description":"Each step names its approver role (vendor manager, compliance, procurement lead, executive); not who approved the previous step. The step due date drives overdue.","decided_in":"assure_workflow_act","where_in_ui":"/assure/workflows/<workflow>"}'),
  ('AP-CA-VERIFY', 'Corrective action verification', '{"module":"assure","approval_type":"CA_VERIFY","approver_role":"internal","maker_checker":true,"sla_days":5,"description":"Verify a completed NCR corrective action; never who completed it.","decided_in":"assure_ca_set_status","where_in_ui":"/assure/quality/ncr/<ncr>"}'),
  ('AP-NCR-CLOSE', 'NCR close', '{"module":"assure","approval_type":"NCR_CLOSE","approver_role":"internal","maker_checker":false,"description":"Close or cancel an NCR once every corrective action is verified.","decided_in":"assure_ncr_close","where_in_ui":"/assure/quality/ncr/<ncr>"}'),
  ('AP-SUPPLIER-STATUS', 'Supplier status change', '{"module":"assure","approval_type":"SUPPLIER_STATUS","approver_role":"srt_lead","maker_checker":false,"description":"SRT lead, Procurement head or admin changes a supplier status with a reason.","decided_in":"assure_set_supplier_status","where_in_ui":"/assure/suppliers"}'),
  ('AP-VENDOR-APPLICATION', 'Vendor application', '{"module":"assure","approval_type":"VENDOR_APPLICATION","approver_role":"procurement","maker_checker":false,"sla_days":5,"description":"Procurement or a vendor manager moves a public application to reviewing, invited, rejected or duplicate.","decided_in":"vendor_application_decide","where_in_ui":"/assure/applications"}'),
  ('AP-SUBSCRIPTION', 'Vendor plan change', '{"module":"assure","approval_type":"SUBSCRIPTION","approver_role":"procurement","maker_checker":false,"sla_days":5,"description":"Procurement actions or declines a vendor plan change request.","decided_in":"assure_set_subscription, assure_decline_subscription_request","where_in_ui":"/assure/suppliers/<supplier>"}'),
  ('AP-CONTRACT-SIGN', 'Contract signature (vendor)', '{"module":"assure","approval_type":"CONTRACT_SIGN","approver_role":"vendor","maker_checker":false,"description":"A vendor signer signs or declines a sent contract in the vendor portal.","decided_in":"vendor_contract_sign","where_in_ui":"/vendor (contracts)"}'),
  -- Client Portal
  ('AP-CLIENT-ACCESS', 'Client access grant', '{"module":"watchtower","approval_type":"CLIENT_ACCESS","approver_role":"admin","maker_checker":false,"description":"Admins grant or revoke Client Portal access (approver or viewer); audited.","decided_in":"client_access_grant, client_access_revoke","where_in_ui":"/watchtower/client-access"}')
) x(code, name, data)
on conflict do nothing;
